import {
    BoundingBox,
    Color,
    FlyController,
    Pose,
    Mat4,
    OrbitController,
    Vec2,
    Vec3
} from 'playcanvas';

import { AnimController } from './controllers/anim-controller.js';
import { easeOut } from './core/math.js';
import { AppController } from './input.js';
import { Picker } from './picker.js';

/** @import { InputController } from 'playcanvas' */

const pose = new Pose();

/**
 * Creates a rotation animation track around the object center
 * 키보드 이동 후에도 올바른 회전을 위해 수정됨
 *
 * @param {Pose} initial - The initial pose of the camera.
 * @param {Vec3} objectCenter - The center point of the object to rotate around.
 * @param {number} [keys] - The number of keys in the animation.
 * @param {number} [duration] - The duration of the animation in seconds.
 * @returns {object} - The animation track object containing position and target keyframes.
 */
const createRotateTrack = (initial, objectCenter, keys = 12, duration = 20) => {
    console.log('=== createRotateTrack called ===');
    console.log('Initial position:', initial.position.x, initial.position.y, initial.position.z);
    console.log('Object center:', objectCenter.x, objectCenter.y, objectCenter.z);
    
    const times = new Array(keys).fill(0).map((_, i) => i / keys * duration);
    const position = [];
    const target = [];

    // 현재 카메라 위치에서 object center로의 벡터
    const radiusVector = new Vec3();
    radiusVector.sub2(initial.position, objectCenter);
    
    console.log('Radius vector:', radiusVector.x, radiusVector.y, radiusVector.z);
    console.log('Distance to center:', radiusVector.length());

    for (let i = 0; i < keys; ++i) {
        const angle = (i / keys) * 360; // 시계방향 회전
        const mat = new Mat4();
        mat.setFromEulerAngles(0, angle, 0);
        
        const rotatedPos = new Vec3();
        mat.transformPoint(radiusVector, rotatedPos);
        rotatedPos.add(objectCenter);

        // Position camera at the rotated position
        position.push(rotatedPos.x);
        position.push(rotatedPos.y);
        position.push(rotatedPos.z);

        // Always look at the object center
        target.push(objectCenter.x);
        target.push(objectCenter.y);
        target.push(objectCenter.z);
        
        if (i === 0) {
            console.log('First keyframe position:', rotatedPos.x, rotatedPos.y, rotatedPos.z);
        }
    }

    console.log('Created track with', keys, 'keyframes, duration:', duration);

    return {
        name: 'rotate',
        duration,
        frameRate: 1,
        target: 'camera',
        loopMode: 'repeat',
        interpolation: 'spline',
        keyframes: {
            times,
            values: {
                position,
                target
            }
        }
    };
};
class Viewer {
    constructor(app, entity, events, state, settings, params) {
        const { background, camera } = settings;
        const { graphicsDevice } = app;

        this.app = app;
        this.entity = entity;
        this.events = events;
        this.state = state;
        this.settings = settings;

        // disable auto render, we'll render only when camera changes
        app.autoRender = false;

        // apply camera animation settings
        entity.camera.clearColor = new Color(background.color);
        entity.camera.fov = camera.fov;

        // handle horizontal fov on canvas resize
        const updateHorizontalFov = () => {
            this.entity.camera.horizontalFov = graphicsDevice.width > graphicsDevice.height;
        };
        graphicsDevice.on('resizecanvas', () => {
            updateHorizontalFov();
            app.renderNextFrame = true;
        });
        updateHorizontalFov();

        // track camera changes
        const prevProj = new Mat4();
        const prevWorld = new Mat4();

        app.on('framerender', () => {
            const world = this.entity.getWorldTransform();
            const proj = this.entity.camera.projectionMatrix;
            const nearlyEquals = (a, b, epsilon = 1e-4) => {
                return !a.some((v, i) => Math.abs(v - b[i]) >= epsilon);
            };

            if (params.ministats) {
                app.renderNextFrame = true;
            }

            if (!app.autoRender && !app.renderNextFrame) {
                if (!nearlyEquals(world.data, prevWorld.data) ||
                    !nearlyEquals(proj.data, prevProj.data)) {
                    app.renderNextFrame = true;
                }
            }

            if (app.renderNextFrame) {
                prevWorld.copy(world);
                prevProj.copy(proj);
            }

            // suppress rendering till we're ready
            if (!state.readyToRender) {
                app.renderNextFrame = false;
            }
        });

        events.on('hqMode:changed', (value) => {
            graphicsDevice.maxPixelRatio = value ? window.devicePixelRatio : 1;
            app.renderNextFrame = true;
        });
        graphicsDevice.maxPixelRatio = state.hqMode ? window.devicePixelRatio : 1;
    }

    // initialize the viewer once gsplat asset is finished loading (so we know its bound etc)
    initialize() {
        const { app, entity, events, state, settings } = this;
    
        // get the gsplat
        const gsplat = app.root.findComponent('gsplat');
    
        // calculate scene bounding box
        const bbox = gsplat?.instance?.meshInstance?.aabb ?? new BoundingBox();
    
        // createRotateTrack 함수 정의 (initialize 함수 내부)
        const createRotateTrack = (initial, objectCenter, keys = 12, duration = 20) => {
            console.log('=== createRotateTrack called ===');
            console.log('Initial position:', initial.position.x, initial.position.y, initial.position.z);
            console.log('Object center:', objectCenter.x, objectCenter.y, objectCenter.z);
            
            const times = new Array(keys).fill(0).map((_, i) => i / keys * duration);
            const position = [];
            const target = [];
    
            const radiusVector = new Vec3();
            radiusVector.sub2(initial.position, objectCenter);
            
            console.log('Radius vector:', radiusVector.x, radiusVector.y, radiusVector.z);
            console.log('Distance to center:', radiusVector.length());
    
            for (let i = 0; i < keys; ++i) {
                const angle = (i / keys) * 360;
                const mat = new Mat4();
                mat.setFromEulerAngles(0, angle, 0);
                
                const rotatedPos = new Vec3();
                mat.transformPoint(radiusVector, rotatedPos);
                rotatedPos.add(objectCenter);
    
                position.push(rotatedPos.x);
                position.push(rotatedPos.y);
                position.push(rotatedPos.z);
    
                target.push(objectCenter.x);
                target.push(objectCenter.y);
                target.push(objectCenter.z);
            }
    
            return {
                name: 'rotate',
                duration,
                frameRate: 1,
                target: 'camera',
                loopMode: 'repeat',
                interpolation: 'spline',
                keyframes: {
                    times,
                    values: {
                        position,
                        target
                    }
                }
            };
        };
    
        // 기존의 framePose, resetPose, userStart, animCamera, orbitCamera, flyCamera 생성 코드...
        const framePose = (() => {
            const sceneSize = bbox.halfExtents.length();
            const distance = sceneSize / Math.sin(entity.camera.fov / 180 * Math.PI * 0.5);
            return new Pose().look(
                new Vec3(2, 1, 2).normalize().mulScalar(distance).add(bbox.center),
                bbox.center
            );
        })();
    
        const resetPose = (() => {
            const { position, target } = settings.camera;
            return new Pose().look(
                new Vec3(position ?? [2, 1, 2]),
                new Vec3(target ?? [0, 0, 0])
            );
        })();
    
        const useReset = settings.camera.position || settings.camera.target || bbox.halfExtents.length() > 100;
        const userStart = (useReset ? resetPose : framePose).clone();
    
        let animCamera = (() => {
            const { animTracks, camera } = settings;
            if (animTracks?.length > 0 && camera.startAnim === 'animTrack') {
                const track = animTracks.find(track => track.name === camera.animTrack);
                if (track) {
                    return AnimController.fromTrack(track);
                }
            }
            return AnimController.fromTrack(createRotateTrack(userStart, bbox.center));
        })();
    
        // 3. OrbitController 설정 시 줌 범위 제한
        const orbitCamera = (() => {
            const orbitCamera = new OrbitController();
            
            // 바운딩 박스를 기준으로 최소 줌 거리 계산
            const boundingRadius = bbox.halfExtents.length();
            const minZoomDistance = boundingRadius * 1.2; // 바운딩 스피어보다 20% 더 멀리
            
            orbitCamera.zoomRange = new Vec2(minZoomDistance, Infinity);
            orbitCamera.pitchRange = new Vec2(-90, 90);
            orbitCamera.rotateDamping = 0.97;
            orbitCamera.moveDamping = 0.97;
            orbitCamera.zoomDamping = 0.97;
            
            console.log('Orbit camera min zoom distance set to:', minZoomDistance);
            console.log('Bounding box center:', bbox.center.x, bbox.center.y, bbox.center.z);
            console.log('Bounding box half extents:', bbox.halfExtents.x, bbox.halfExtents.y, bbox.halfExtents.z);
            
            return orbitCamera;
        })();
    
        const flyCamera = (() => {
            const flyCamera = new FlyController();
            flyCamera.pitchRange = new Vec2(-90, 90);
            flyCamera.rotateDamping = 0.97;
            flyCamera.moveDamping = 0.97;
            return flyCamera;
        })();
    
        const getCamera = (cameraMode) => {
            switch (cameraMode) {
                case 'orbit': return orbitCamera;
                case 'anim': return animCamera;
                case 'fly': return flyCamera;
            }
        };
    
        // 상태 설정
        state.hasAnimation = !!animCamera;
        state.animationDuration = animCamera ? animCamera.cursor.duration : 0;
        if (animCamera) {
            state.cameraMode = 'anim';
        }
    
        const activePose = new Pose();
        const controller = new AppController(app.graphicsDevice.canvas, entity.camera);
        controller.moveSpeed = Math.max(0.05, Math.min(1, bbox.halfExtents.length() * 0.0001)) * 200;
    
        if (state.cameraMode === 'anim') {
            activePose.copy(animCamera.update(controller.frame, 0));
        } else {
            activePose.copy(userStart);
        }
    
        orbitCamera.attach(activePose, false);
        flyCamera.attach(activePose, false);
    
        let transitionTimer = 0;
        const prevPose = new Pose();
        let prevCamera = null;
        let prevCameraMode = 'orbit';
    
        // doReset 함수 정의 (initialize 함수 내부)
        const doReset = (pose) => {
            console.log('=== doReset called ===');
            console.log('Current camera mode:', state.cameraMode);
            
            if (animCamera) {
                const currentPos = entity.getPosition();
                const startPose = new Pose();
                startPose.position.copy(currentPos);
                startPose.look(currentPos, bbox.center);
                
                const newAnimTrack = createRotateTrack(startPose, bbox.center);
                animCamera = AnimController.fromTrack(newAnimTrack);
                
                orbitCamera.detach();
                flyCamera.detach();
                
                state.animationDuration = animCamera.cursor.duration;
                state.cameraMode = 'anim';
                state.animationPaused = false;
                
                animCamera.cursor.reset(animCamera.cursor.duration, animCamera.cursor.loopMode);
                activePose.copy(startPose);
                
                console.log('Animation reset complete');
            }
        };
    
        // inputEvent 핸들러 (initialize 함수 내부)
        events.on('inputEvent', async (eventName, event) => {
            switch (eventName) {
                case 'frame':
                    doReset(framePose);
                    break;
                case 'reset':
                    doReset(resetPose);
                    break;
                case 'cancel':
                case 'interrupt':
                    if (state.cameraMode === 'anim') {
                        console.log('Interrupting animation, switching to orbit');
                        
                        const currentOrbitPose = new Pose();
                        currentOrbitPose.position.copy(activePose.position);
                        currentOrbitPose.look(activePose.position, bbox.center);
                        
                        state.cameraMode = 'orbit';
                        orbitCamera.attach(currentOrbitPose, false);
                        
                        console.log('Switched to orbit mode at current position');
                    }
                    break;
                case 'dblclick': {
                    // 더블클릭 처리 코드...
                    break;
                }
            }
        });
    
        // 카메라 모드 변경 핸들러 (initialize 함수 내부)
        events.on('cameraMode:changed', (value, prev) => {
            console.log('=== Camera mode changed ===');
            console.log('From:', prev, 'To:', value);
            
            prevCameraMode = prev;
            prevPose.copy(activePose);
            
            if (prevCamera) {
                prevCamera.detach();
            }
            prevCamera = getCamera(prev);
    
            switch (value) {
                case 'orbit': {
                    console.log('Switching to orbit mode');
                    
                    const orbitPose = new Pose();
                    orbitPose.position.copy(activePose.position);
                    orbitPose.look(activePose.position, bbox.center);
                    
                    orbitCamera.attach(orbitPose, false);
                    
                    console.log('Orbit camera attached');
                    break;
                }
                case 'fly': {
                    console.log('Switching to fly mode');
                    flyCamera.attach(activePose, false);
                    break;
                }
                case 'anim': {
                    console.log('Switching to anim mode');
                    orbitCamera.detach();
                    flyCamera.detach();
                    break;
                }
            }
    
            if (!state.snap) {
                transitionTimer = 0;
            }
            state.snap = false;
            
            console.log('Camera mode switch complete');
        });

         // 3. 더 부드러운 제한을 위한 개선된 업데이트 로직
        app.on('update', (deltaTime) => {
            if (app.xr.active) {
                return;
            }

            controller.update(deltaTime, state, activePose.distance);

            if (state.cameraMode === 'fly') {
                events.fire('touchJoystickUpdate', controller.joystick.base, controller.joystick.stick);
            }

            const dt = state.cameraMode === 'anim' ?
                (state.animationPaused ? 0 : deltaTime * transitionTimer) :
                deltaTime;

            const newPose = getCamera(state.cameraMode).update(controller.frame, dt);
            
            // *** Fly 모드에서 개선된 바운더리 체크 ***
            if (state.cameraMode === 'fly') {
                const center = bbox.center;
                const radius = bbox.halfExtents.length();
                const margin = 1.0; // 마진을 좀 더 크게 설정
                const minDistance = radius + margin;
                const currentDistance = newPose.position.distance(center);
                
                if (currentDistance < minDistance) {
                    console.log('Fly camera too close to object');
                    console.log('Current distance:', currentDistance, 'Min distance:', minDistance);
                    
                    // 현재 이동 방향을 유지하면서 경계에서 멈추기
                    const directionFromCenter = new Vec3();
                    directionFromCenter.sub2(newPose.position, center).normalize();
                    
                    // 경계 지점으로 위치 조정
                    const boundaryPosition = new Vec3();
                    boundaryPosition.copy(directionFromCenter).mulScalar(minDistance).add(center);
                    
                    newPose.position.copy(boundaryPosition);
                    
                    console.log('Position adjusted to boundary');
                }
            }
            
            pose.copy(newPose);

            // 카메라 전환 시 블렌딩
            if (transitionTimer < 1) {
                transitionTimer = Math.min(1, transitionTimer + deltaTime);
                if (transitionTimer < 1 && prevCamera) {
                    pose.lerp(prevPose, pose, easeOut(transitionTimer));
                }
            }

            activePose.copy(pose);
            entity.setPosition(activePose.position);
            entity.setEulerAngles(activePose.angles);

            if (state.cameraMode === 'anim') {
                state.animationTime = animCamera.cursor.value;
            }
        });

        // 2. 카메라 모드 변경 시 올바른 target 설정
        events.on('cameraMode:changed', (value, prev) => {
            console.log('=== Camera mode changed ===');
            console.log('From:', prev, 'To:', value);
            console.log('Current activePose:', activePose.position.x, activePose.position.y, activePose.position.z);
            
            prevCameraMode = prev;
            prevPose.copy(activePose);
            
            // 이전 카메라 완전히 분리
            if (prevCamera) {
                prevCamera.detach();
            }
            prevCamera = getCamera(prev);

            switch (value) {
                case 'orbit': {
                    console.log('Switching to orbit mode');
                    
                    // *** 핵심: object center를 바라보는 pose로 orbit 설정 ***
                    const orbitPose = new Pose();
                    orbitPose.position.copy(activePose.position);
                    orbitPose.look(activePose.position, bbox.center);
                    
                    // orbit 컨트롤러를 올바른 target으로 attach
                    orbitCamera.attach(orbitPose, false);
                    
                    console.log('Orbit camera attached');
                    console.log('- Position:', orbitPose.position.x, orbitPose.position.y, orbitPose.position.z);
                    console.log('- Looking at:', bbox.center.x, bbox.center.y, bbox.center.z);
                    console.log('- Distance:', orbitPose.position.distance(bbox.center));
                    
                    break;
                }
                case 'fly': {
                    console.log('Switching to fly mode');
                    flyCamera.attach(activePose, false);
                    break;
                }
                case 'anim': {
                    console.log('Switching to anim mode');
                    // 애니메이션 모드로 전환할 때는 모든 다른 컨트롤러 분리
                    orbitCamera.detach();
                    flyCamera.detach();
                    break;
                }
            }

            // reset camera transition timer
            if (!state.snap) {
                transitionTimer = 0;
            }
            state.snap = false;
            
            console.log('Camera mode switch complete');
        });

        events.on('setAnimationTime', (time) => {
            if (animCamera) {
                animCamera.cursor.value = time;

                // switch to animation camera if we're not already there
                if (state.cameraMode !== 'anim') {
                    state.cameraMode = 'anim';
                }
            }
        });

        events.on('resetAnimation', () => {
            if (animCamera) {
                animCamera.cursor.reset(animCamera.cursor.duration, animCamera.cursor.loopMode);
            }
        });

        // pick orbit camera focus point on double click
        let picker = null;
        events.on('inputEvent', async (eventName, event) => {
            switch (eventName) {
                case 'dblclick': {
                    if (!picker) {
                        picker = new Picker(app, entity);
                    }
                    const result = await picker.pick(event.offsetX, event.offsetY);
                    if (result) {
                        if (state.cameraMode !== 'orbit') {
                            state.snap = true;
                            state.cameraMode = 'orbit';
                        }

                        // snap distance of focus to picked point to interpolate rotation only
                        activePose.distance = activePose.position.distance(result);
                        orbitCamera.attach(activePose, false);

                        orbitCamera.attach(pose.look(activePose.position, result), true);
                    }
                    break;
                }
            }
        });

        // initialize the camera entity to initial position and kick off the
        // first scene sort (which usually happens during render)
        entity.setPosition(activePose.position);
        entity.setEulerAngles(activePose.angles);
        gsplat?.instance?.sort(entity);

        // handle gsplat sort updates
        gsplat?.instance?.sorter?.on('updated', () => {
            // request frame render when sorting changes
            app.renderNextFrame = true;

            if (!state.readyToRender) {
                // we're ready to render once the first sort has completed
                state.readyToRender = true;

                // wait for the first valid frame to complete rendering
                const frameHandle = app.on('frameend', () => {
                    frameHandle.off();

                    events.fire('firstFrame');

                    // emit first frame event on window
                    window.firstFrame?.();
                });
            }
        });

        // 1. 구형(Sphere) 기반 바운더리 체크로 변경
        const isPositionInsideBounds = (position, boundingBox, margin = 0.5) => {
            const center = boundingBox.center;
            const radius = boundingBox.halfExtents.length(); // 바운딩 스피어 반지름
            const distance = position.distance(center);
            
            return distance < (radius + margin);
        };
        // 2. 안전한 위치로 조정하는 함수 - 더 자연스러운 방식
        const getSafePosition = (desiredPosition, currentPosition, boundingBox, margin = 0.5) => {
            const center = boundingBox.center;
            const radius = boundingBox.halfExtents.length();
            const minDistance = radius + margin;
            
            const distanceToCenter = desiredPosition.distance(center);
            
            // 바운더리 밖에 있으면 그대로 허용
            if (distanceToCenter >= minDistance) {
                return desiredPosition.clone();
            }
            
            // 바운더리 안쪽으로 들어가려고 하면, 현재 위치에서 중심으로의 방향을 유지하면서
            // 최소 거리 지점으로 위치 조정
            console.log('Position inside bounds detected');
            console.log('Desired position:', desiredPosition.x, desiredPosition.y, desiredPosition.z);
            console.log('Distance to center:', distanceToCenter, 'Min distance:', minDistance);
            
            // 현재 위치에서 중심으로의 방향 벡터 계산
            const directionFromCenter = new Vec3();
            directionFromCenter.sub2(currentPosition, center);
            
            // 방향이 없으면 (중심에 너무 가까우면) 기본 방향 사용
            if (directionFromCenter.length() < 0.01) {
                directionFromCenter.set(0, 0, 1); // 기본적으로 Z축 방향
            } else {
                directionFromCenter.normalize();
            }
            
            // 최소 거리 지점으로 위치 설정
            const safePosition = new Vec3();
            safePosition.copy(directionFromCenter).mulScalar(minDistance).add(center);
            
            console.log('Safe position:', safePosition.x, safePosition.y, safePosition.z);
            console.log('New distance to center:', safePosition.distance(center));
            
            return safePosition;
        };
    }
}

export { Viewer };
